  <script>
    if (new URLSearchParams(window.location.search).get('capture') === '1') document.body.classList.add('capture');

    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(event) {
      if (!event.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(event) {
      if (event.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var currentTheme = 'dark';
    function applyTheme(theme) {
      document.documentElement.className = 'theme-' + theme;
      document.getElementById('themeIcon').textContent = theme === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = theme === 'dark' ? 'Dark' : 'Light';
      currentTheme = theme;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }

    function downloadImage() {
      var node = document.getElementById('main-content');
      htmlToImage.toPng(node, { pixelRatio: 1, backgroundColor: '#08111f' }).then(function(dataUrl) {
        var link = document.createElement('a');
        link.download = 'js-framework-benchmark-poster.png';
        link.href = dataUrl;
        link.click();
      });
    }

    var chartsBuilt = false;
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js library not loaded - check CDN inclusion'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          ctx.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) { console.error('Chart initialization failed for ' + canvasId, error); return null; }
      }
    };

    function buildRunsChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      ChartManager.safeInit('runsChart', {
        type: 'bar',
        data: { labels: ['2017–19','2020','2021','2022','2023','2024','2025','2026'], datasets: [{ label: 'Official runs', data: [4,5,9,13,12,12,12,3], backgroundColor: 'rgba(41,169,255,0.85)', borderRadius: 4 }] },
        options: { responsive: true, maintainAspectRatio: false, plugins: { tooltip: { enabled: true }, legend: { display: false } }, layout: { padding: 30 }, scales: { x: { grid: { color: 'rgba(255,255,255,0.04)' } }, y: { grid: { color: 'rgba(255,255,255,0.04)' } } } }
      });
      chartsBuilt = true;
    }
    function onThemeChange() { if (chartsBuilt) buildRunsChart(); }
    buildRunsChart();
  </script>
</body>
